class Solution {
public:
    int largestCombination(std::vector<int>& candidates) {
        int ans = 0;
        for (int b = 0; b < 25; ++b) {
            int cnt = 0;
            for (int x : candidates) {
                if ((x >> b) & 1) ++cnt;
            }
            ans = std::max(ans, cnt);
        }
        return ans;
    }
};

class Solution {
    public int largestCombination(int[] candidates) {
        int ans = 0;
        for (int b = 0; b < 25; b++) {
            int cnt = 0;
            for (int x : candidates) {
                if (((x >> b) & 1) == 1) cnt++;
            }
            ans = Math.max(ans, cnt);
        }
        return ans;
    }
}

var largestCombination = function(candidates) {
    let ans = 0;
    for (let b = 0; b < 25; b++) {
        let cnt = 0;
        for (let i = 0; i < candidates.length; i++) {
            if ((candidates[i] >> b) & 1) cnt++;
        }
        if (cnt > ans) ans = cnt;
    }
    return ans;
};
